/**
 * Dokan Stripe Connect — WooCommerce Blocks integration entry.
 *
 * Registers the Payment Elements front-end as a block-checkout payment method.
 * Pairs with the server-side {@link \WeDevs\DokanPro\Modules\Stripe\Blocks\StripeConnectBlock}.
 *
 * @since 5.0.7
 */
import { __ } from '@wordpress/i18n';
import {
    registerPaymentMethod,
    registerExpressPaymentMethod,
    // @ts-ignore
} from '@woocommerce/blocks-registry';
// @ts-ignore
// eslint-disable-next-line import/no-unresolved
import { getSetting } from '@woocommerce/settings';

import PaymentElements from './PaymentElements';
import SavedTokenContent from './SavedTokenContent';
import ExpressCheckout from './ExpressCheckout';

const settings = getSetting( 'dokan-stripe-connect_data', {} );
const gatewayId = 'dokan-stripe-connect';

const Label = ( props: any ) => {
    const { PaymentMethodLabel } = props.components;
    return (
        <PaymentMethodLabel
            text={ settings?.title ?? __( 'Stripe Connect', 'dokan' ) }
        />
    );
};

const EditContent = () => (
    <>
        <h4>{ settings?.title }</h4>
        <p>{ settings?.description }</p>
    </>
);

const paymentMethodOptions = {
    name: gatewayId,
    gatewayId,
    paymentMethodId: gatewayId,
    title: settings?.title ?? __( 'Stripe Connect', 'dokan' ),
    label: <Label />,
    content: <PaymentElements />,
    savedTokenComponent: <SavedTokenContent />,
    edit: <EditContent />,
    canMakePayment: () => Boolean( settings?.publishable_key ),
    ariaLabel: __( 'Dokan Stripe Connect', 'dokan' ),
    supports: {
        showSaveOption: settings?.show_save_option ?? false,
        features: settings?.supports ?? [ 'products' ],
    },
};

const expressPaymentMethodOptions = {
    ...paymentMethodOptions,
    name: `${ gatewayId }-express`,
    title: __( 'Stripe Express Checkout', 'dokan' ),
    content: <ExpressCheckout />,
    supports: {
        features: settings?.supports ?? [ 'products' ],
        style: [ 'height', 'borderRadius' ],
    },
};

/**
 * Register the payment method.
 *
 * @see https://developer.woocommerce.com/docs/cart-and-checkout-payment-method-integration-for-the-checkout-block/#0-client-side-integration
 * @see https://github.com/woocommerce/woocommerce-blocks/blob/trunk/docs/internal-developers/block-client-apis/checkout/checkout-api.md#usepaymentmethodinterface
 * @see https://developer.woocommerce.com/docs/block-development/cart-and-checkout-blocks/checkout-payment-methods/payment-method-integration/#client-side-integration
 * @see https://developer.woocommerce.com/docs/block-development/cart-and-checkout-blocks/checkout-payment-methods/payment-method-integration/
 */
registerPaymentMethod( paymentMethodOptions );
// Express Checkout — Apple Pay, Google Pay, Link in a single widget.
registerExpressPaymentMethod( expressPaymentMethodOptions );
