/**
 * Saved-token slot for block checkout. WC Blocks renders this when a customer
 * picks an existing saved card. Unlike the new-card path, WC Blocks does NOT
 * automatically inject `wc-{gateway}-payment-token` into the Store API
 * `payment_data` — the savedTokenComponent must do it via `onPaymentSetup`.
 *
 * The server-side {@link \WeDevs\DokanPro\Modules\Stripe\Blocks\StripeConnectBlock::capture_payment_data_from_blocks}
 * reads that key into `$_POST` so `is_using_saved_payment_method()` can route
 * the request to {@link \WeDevs\DokanPro\Modules\Stripe\Processors\TokenProcessor}.
 *
 * @since 5.0.7
 */
import { __ } from '@wordpress/i18n';
// @ts-ignore
// eslint-disable-next-line import/no-unresolved
import { getSetting } from '@woocommerce/settings';

type Props = {
    token?: string | number;
    activePaymentMethod?: string;
    components?: {
        PaymentMethodLabel?: any;
    };
    eventRegistration?: {
        onPaymentSetup: ( cb: () => Promise< any > | any ) => () => void;
    };
    emitResponse?: {
        responseTypes: { SUCCESS: string; ERROR: string };
    };
};

const SavedTokenContent = ( props: Props ) => {
    const settings: { title?: string } = getSetting(
        'dokan-stripe-connect_data',
        {}
    );
    const PaymentMethodLabel = props.components?.PaymentMethodLabel;
    const labelText = settings?.title ?? __( 'Stripe', 'dokan' );

    if ( PaymentMethodLabel ) {
        return <PaymentMethodLabel text={ labelText } />;
    }

    return <p>{ labelText }</p>;
};

export default SavedTokenContent;
