/**
 * Stripe Elements wrapper for Dokan Stripe Connect on block checkout.
 *
 * Responsibilities:
 *  - load Stripe.js with the publishable key from the block settings;
 *  - call the Dokan PE create-intent AJAX route to obtain a client_secret;
 *  - render <Elements> + the actual <PaymentElement> mount via DefaultPaymentForm.
 *
 * @since 5.0.7
 */
import { useEffect, useMemo, useRef, useState } from '@wordpress/element';
import { useSelect } from '@wordpress/data';
import { __ } from '@wordpress/i18n';
import {
    loadStripe,
    type Stripe,
    type StripeElementsOptions,
} from '@stripe/stripe-js';
import { Elements } from '@stripe/react-stripe-js';
// @ts-ignore
// eslint-disable-next-line import/no-unresolved
import { getSetting } from '@woocommerce/settings';

import DefaultPaymentForm from './DefaultPaymentForm';
import {
    fetchPaymentIntent,
    resetPaymentIntent,
    type IntentType,
} from '../shared/api';

type BlockSettings = {
    publishable_key: string;
    description?: string;
    testmode?: boolean;
    locale?: string;
};

type IntentResponse = {
    type: IntentType;
    client_secret: string;
    intent_id: string;
};

interface State {
    intent: IntentResponse | null;
    error: string | null;
    isLoading: boolean;
}

const initialState: State = {
    intent: null,
    error: null,
    isLoading: true,
};

const PaymentElements = ( props: any ) => {
    const [ state, setState ] = useState< State >( initialState );
    const { components } = props;
    const LoadingMask = components?.LoadingMask;
    const ValidationInputError = components?.ValidationInputError;

    const lastAmount = useRef< number | null >( null );

    const cartTotal = useSelect( ( select: any ) => {
        return select( 'wc/store/cart' )?.getCartData()?.totals?.total_price;
    }, [] );

    const settings: BlockSettings = getSetting(
        'dokan-stripe-connect_data',
        {}
    );
    const { publishable_key: publishableKey } = settings;

    const stripePromise = useMemo< Promise< Stripe | null > | null >( () => {
        if ( ! publishableKey ) {
            return null;
        }
        return loadStripe( publishableKey );
    }, [ publishableKey ] );

    useEffect( () => {
        const currentAmount = Number( cartTotal || 0 );

        // Skip if we already have an intent for this specific amount to prevent
        // multiple identical REST calls during Block-checkout re-renders.
        if (
            state.intent &&
            currentAmount === lastAmount.current &&
            currentAmount > 0
        ) {
            return;
        }

        const fetchIntent = async () => {
            setState( ( prev ) => ( { ...prev, isLoading: true } ) );
            try {
                lastAmount.current = currentAmount;
                resetPaymentIntent();
                const intent = await fetchPaymentIntent( {
                    amount: currentAmount || undefined,
                } );

                if ( ! intent ) {
                    setState( {
                        intent: null,
                        error: __( 'Could not initialize Stripe.', 'dokan' ),
                        isLoading: false,
                    } );
                    return;
                }
                setState( {
                    intent: {
                        type: intent.type,
                        client_secret: intent.client_secret,
                        intent_id: intent.intent_id,
                    },
                    error: null,
                    isLoading: false,
                } );
            } catch ( e: any ) {
                setState( {
                    intent: null,
                    error:
                        e?.message ||
                        __( 'Could not initialize Stripe.', 'dokan' ),
                    isLoading: false,
                } );
            }
        };

        void fetchIntent();
    }, [ cartTotal, state.intent ] );

    const elementOptions: StripeElementsOptions = useMemo(
        () => ( {
            clientSecret: state.intent?.client_secret ?? '',
            loader: 'auto',
            appearance: { theme: 'stripe' },
        } ),
        [ state.intent?.client_secret ]
    );

    if ( state.error && ValidationInputError ) {
        return (
            <ValidationInputError
                errorMessage={ __( 'Error:', 'dokan' ) + state.error }
                propertyName=""
                elementId=""
            />
        );
    }

    if ( state.isLoading || ! state.intent?.client_secret ) {
        if ( LoadingMask ) {
            return <LoadingMask showSpinner={ true } isLoading={ true } />;
        }
        return <p>{ __( 'Loading…', 'dokan' ) }</p>;
    }

    return (
        <div
            className="dokan-stripe-connect-payment-element"
            key={ state.intent.intent_id }
        >
            { settings.description && (
                <p
                    className="dokan-stripe-connect-description"
                    dangerouslySetInnerHTML={ {
                        __html: settings.description,
                    } }
                />
            ) }
            <Elements stripe={ stripePromise } options={ elementOptions }>
                <DefaultPaymentForm
                    paymentIntent={ state.intent }
                    { ...props }
                />
            </Elements>
        </div>
    );
};

export default PaymentElements;
