/**
 * Express Checkout (Apple Pay / Google Pay / Link) for WC Blocks.
 *
 * Uses Stripe's <ExpressCheckoutElement /> which surfaces every wallet the
 * Dashboard's Payment Method Configurations allow in a single widget.
 *
 * On wallet confirm we POST directly to `wc-ajax=checkout` with the wallet's
 * billing/shipping + the confirmed PaymentIntent id. This bypasses the WC
 * Blocks express-payment lifecycle (which requires cart-side validation that
 * doesn't get the wallet's address in time) and matches the classic flow.
 *
 * @since 5.0.7
 */
import { useMemo, useState } from '@wordpress/element';
import {
    loadStripe,
    type Stripe,
    type StripeElementsOptions,
} from '@stripe/stripe-js';
import {
    Elements,
    ExpressCheckoutElement,
    useStripe,
    useElements,
} from '@stripe/react-stripe-js';
// @ts-ignore
// eslint-disable-next-line import/no-unresolved
import { getSetting } from '@woocommerce/settings';

import { fetchPaymentIntent, resetPaymentIntent } from '../shared/api';
import { submitWalletCheckout } from '../shared/checkout';

type BlockSettings = {
    publishable_key: string;
    locale?: string;
    checkout_nonce?: string;
    setup_future_usage?: '' | 'off_session' | 'on_session';
};

const settings: BlockSettings = getSetting( 'dokan-stripe-connect_data', {} );

const InnerExpress = ( props: any ) => {
    const stripe = useStripe();
    const elements = useElements();
    const [ ready, setReady ] = useState( false );
    const [ empty, setEmpty ] = useState( false );
    const [ submitting, setSubmitting ] = useState( false );

    const setExpressError: ( ( msg: string ) => void ) | undefined =
        props?.setExpressPaymentError;

    const handleConfirm = async ( event: any ) => {
        if ( ! stripe || ! elements || submitting ) {
            event?.paymentFailed?.( { reason: 'fail' } );
            return;
        }

        event?.preventDefault?.();
        setSubmitting( true );

        // Stripe lets us call paymentFailed() only BEFORE confirmPayment
        // succeeds. After that, the wallet sheet has closed and any further
        // call throws an IntegrationError. Track that boundary here.
        let confirmed = false;

        const fail = ( message?: string ) => {
            // eslint-disable-next-line no-console
            console.warn( '[Dokan Stripe Express Block]', message );
            if ( message && setExpressError ) {
                setExpressError( message );
            }
            if ( ! confirmed ) {
                event?.paymentFailed?.( { reason: 'fail' } );
            }
            setSubmitting( false );
        };

        const { error: submitError } = await elements.submit();
        if ( submitError ) {
            fail( submitError.message );
            return;
        }

        resetPaymentIntent();
        // Cart total in the store's minor unit, from the Blocks billing prop
        // (same source the wrapper uses to size the Express element). The
        // server re-derives the authoritative amount from the order, so this
        // is only a hint to keep the intent in sync during re-renders.
        const cartTotalMinor =
            Number(
                props?.billing?.cartTotal?.value ??
                    props?.billing?.cartTotalItems?.[ 0 ]?.value ??
                    0
            ) || undefined;
        const intent = await fetchPaymentIntent( {
            amount: cartTotalMinor,
        } );
        if ( ! intent?.client_secret || ! intent?.intent_id ) {
            fail( 'payment-intent request failed' );
            return;
        }

        const { error } = await stripe.confirmPayment( {
            elements,
            clientSecret: intent.client_secret,
            confirmParams: {
                return_url: window.location.href,
            },
            redirect: 'if_required',
        } );
        if ( error ) {
            fail( error.message );
            return;
        }

        confirmed = true;
        const result = await submitWalletCheckout(
            intent.intent_id,
            event,
            settings.checkout_nonce ?? ''
        );
        if ( ! result.ok ) {
            fail( result.message );
            return;
        }
        window.location.assign( result.redirect );
    };

    const handleReady = ( ev: any ) => {
        const available = ev?.availablePaymentMethods;
        const anyWallet =
            available && Object.values( available ).some( ( v ) => v === true );
        if ( ! anyWallet ) {
            setEmpty( true );
            return;
        }
        setReady( true );
    };

    if ( empty ) {
        return null;
    }

    return (
        <div
            className="dokan-stripe-pe-express-block"
            style={ { position: 'relative', minHeight: 48 } }
        >
            { submitting && (
                <div className="dokan-stripe-pe-express-loading-overlay">
                    <div
                        className="dokan-stripe-pe-express-spinner"
                        aria-hidden="true"
                    />
                </div>
            ) }
            { ! ready && (
                <div
                    className="dokan-stripe-pe-express-block-spinner dokan-stripe-pe-express-spinner"
                    aria-hidden="true"
                />
            ) }
            <div
                style={ {
                    opacity: ready ? 1 : 0,
                    transition: 'opacity 150ms ease',
                } }
            >
                <ExpressCheckoutElement
                    onConfirm={ handleConfirm }
                    onReady={ handleReady }
                    options={ {
                        buttonType: { applePay: 'buy', googlePay: 'buy' },
                        paymentMethods: {
                            applePay: 'always',
                            googlePay: 'always',
                        },
                        emailRequired: true,
                        billingAddressRequired: true,
                        phoneNumberRequired: true,
                        shippingAddressRequired: false,
                    } }
                />
            </div>
        </div>
    );
};

const ExpressCheckout = ( props: any ) => {
    const stripePromise: Promise< Stripe | null > | null = useMemo( () => {
        if ( ! settings.publishable_key ) {
            return null;
        }
        return loadStripe( settings.publishable_key );
    }, [] );

    const cartTotalValue = Number(
        props?.billing?.cartTotal?.value ??
            props?.billing?.cartTotalItems?.[ 0 ]?.value ??
            0
    );

    if ( cartTotalValue <= 0 ) {
        return null;
    }
    const currency = ( props?.billing?.currency?.code ?? 'usd' ).toLowerCase();
    const elementOptions: StripeElementsOptions = {
        mode: 'payment',
        amount: cartTotalValue,
        currency,
        appearance: { theme: 'stripe' },
        loader: 'auto',
    };

    // Deferred-intent Elements must declare the same setup_future_usage the
    // server stamps on the PaymentIntent, else confirmPayment rejects with a
    // mismatch. Server sends 'off_session' when the cart should save the card.
    if (
        settings.setup_future_usage === 'off_session' ||
        settings.setup_future_usage === 'on_session'
    ) {
        elementOptions.setupFutureUsage = settings.setup_future_usage;
    }

    return (
        <Elements stripe={ stripePromise } options={ elementOptions }>
            <InnerExpress { ...props } />
        </Elements>
    );
};

export default ExpressCheckout;
