/**
 * Inner <PaymentElement /> mount + checkout-event wiring.
 *
 * @since 5.0.7
 */
import { __ } from '@wordpress/i18n';
import {
    PaymentElement,
    useElements,
    useStripe,
} from '@stripe/react-stripe-js';
import type { StripePaymentElementOptions } from '@stripe/stripe-js';
import { useEffect, useRef } from '@wordpress/element';

import { confirmWalletGesture } from '../shared/checkout';

type Props = {
    paymentIntent: {
        type?: 'payment' | 'setup';
        client_secret: string;
        intent_id: string;
        subscription_id?: string;
    };
    activePaymentMethod: string;
    eventRegistration: {
        onPaymentSetup: ( cb: () => Promise< any > ) => () => void;
        onCheckoutSuccess: (
            cb: ( resp: any ) => Promise< any >
        ) => () => void;
    };
    emitResponse: {
        responseTypes: { SUCCESS: string; ERROR: string };
    };
    shouldSavePayment?: boolean;
    billing?: any;
};

const DefaultPaymentForm = ( props: Props ) => {
    const {
        paymentIntent,
        eventRegistration,
        emitResponse,
        shouldSavePayment,
        activePaymentMethod,
    } = props;
    const { onPaymentSetup, onCheckoutSuccess } = eventRegistration;

    const stripe = useStripe();
    const elements = useElements();

    // Method type currently selected in the Payment Element accordion. Read in
    // onCheckoutSuccess to decide whether the wallet gesture popup is needed.
    const selectedTypeRef = useRef< string >( '' );

    // Tell WC Blocks which PI to attach to the order being placed.
    useEffect( () => {
        const unsubscribe = onPaymentSetup( async () => {
            if ( 'dokan-stripe-connect' !== activePaymentMethod ) {
                return false;
            }
            if ( ! paymentIntent?.intent_id ) {
                return {
                    type: emitResponse.responseTypes.ERROR,
                    message: __( 'Stripe payment is not ready.', 'dokan' ),
                };
            }

            const paymentMethodData: Record< string, any > = {
                dokan_stripe_payment_intent_id: paymentIntent.intent_id,
            };

            if ( paymentIntent.subscription_id ) {
                paymentMethodData.dokan_stripe_subscription_id =
                    paymentIntent.subscription_id;
            }

            if ( shouldSavePayment ) {
                paymentMethodData[
                    'wc-dokan-stripe-connect-new-payment-method'
                ] = '1';
            }

            return {
                type: emitResponse.responseTypes.SUCCESS,
                meta: { paymentMethodData },
            };
        } );

        return () => unsubscribe();
    }, [
        activePaymentMethod,
        paymentIntent?.intent_id,
        paymentIntent?.subscription_id,
        shouldSavePayment,
        emitResponse.responseTypes.SUCCESS,
        emitResponse.responseTypes.ERROR,
        onPaymentSetup,
    ] );

    // After WC places the order server-side, run stripe.confirmPayment.
    useEffect( () => {
        const unsubscribe = onCheckoutSuccess( async ( successResponse ) => {
            if ( ! stripe || ! elements ) {
                return {
                    type: emitResponse.responseTypes.ERROR,
                    message: __( 'Stripe.js is not loaded.', 'dokan' ),
                };
            }

            // Apple Pay / Google Pay: open the sheet from the popup's fresh
            // gesture so Safari permits it. No-op for card / Link.
            if ( ! ( await confirmWalletGesture( selectedTypeRef.current ) ) ) {
                return {
                    type: emitResponse.responseTypes.ERROR,
                    message: __( 'Payment cancelled.', 'dokan' ),
                };
            }

            const isSetup = paymentIntent?.type === 'setup';
            const confirmArgs = {
                elements,
                confirmParams: {
                    return_url: successResponse?.redirectUrl,
                },
                redirect: 'always' as const,
            };

            const { error } = isSetup
                ? await stripe.confirmSetup( confirmArgs )
                : await stripe.confirmPayment( confirmArgs );

            if ( error ) {
                return {
                    type: emitResponse.responseTypes.ERROR,
                    message: error.message,
                };
            }

            return { type: emitResponse.responseTypes.SUCCESS };
        } );

        return () => unsubscribe();
    }, [
        stripe,
        elements,
        paymentIntent?.type,
        emitResponse.responseTypes.SUCCESS,
        emitResponse.responseTypes.ERROR,
        onCheckoutSuccess,
    ] );

    const paymentElementOptions: StripePaymentElementOptions = {
        layout: {
            type: 'accordion',
            defaultCollapsed: false,
            radios: true,
            spacedAccordionItems: false,
        },
        paymentMethodOrder: [ 'card', 'apple_pay', 'google_pay', 'link' ],
    };

    return (
        <PaymentElement
            id="dokan-stripe-connect-payment-element"
            options={ paymentElementOptions }
            onChange={ ( event: any ) => {
                selectedTypeRef.current = event?.value?.type ?? '';
            } }
        />
    );
};

export default DefaultPaymentForm;
